<?php
/**
 * NaturaFruct — contact form handler.
 * Spam protection: honeypot field, minimum fill time, JS interaction token,
 * per-IP rate limit, link limit, header-injection checks, optional Cloudflare Turnstile.
 * Settings: contact-config.php. Field labels: contact-labels.json (generated by build.mjs).
 */
declare(strict_types=1);

header('X-Robots-Tag: noindex, nofollow');
header('Cache-Control: no-store');

$cfg    = require __DIR__ . '/contact-config.php';
$labels = json_decode((string) @file_get_contents(__DIR__ . '/contact-labels.json'), true) ?: [];
$isAjax = strpos($_SERVER['HTTP_ACCEPT'] ?? '', 'application/json') !== false;
$lang   = (($_POST['lang'] ?? 'ro') === 'en') ? 'en' : 'ro';

function respond(bool $ok, int $code = 200, array $extra = []): void
{
    global $isAjax, $lang;
    if ($isAjax) {
        http_response_code($code);
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['ok' => $ok] + $extra, JSON_UNESCAPED_UNICODE);
        exit;
    }
    $base = $lang === 'en' ? '/en/contact/' : '/contact/';
    header('Location: ' . $base . '?' . ($ok ? 'sent=1' : 'error=1') . '#form', true, 303);
    exit;
}

function clean(string $key, int $max): string
{
    $v = trim((string) ($_POST[$key] ?? ''));
    $v = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', '', $v) ?? '';
    return mb_substr($v, 0, $max);
}

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    header('Allow: POST');
    respond(false, 405, ['error' => 'method']);
}

// 1) Honeypot: real users never see this field. Pretend success so bots don't adapt.
if (!empty($_POST['website'])) respond(true);

// 2) Timing + JS interaction token
$ts  = (int) ($_POST['ts'] ?? 0);
$hk  = (string) ($_POST['hk'] ?? '');
if ($ts <= 0 || !preg_match('/^h[a-z0-9]{8,40}$/', $hk)) respond(false, 400, ['error' => 'js']);
$age = time() - intdiv($ts, 1000);
if ($age < (int) $cfg['min_seconds']) respond(true);          // filled too fast → bot
if ($age > 86400 * 3) respond(false, 400, ['error' => 'expired']);

// 3) Rate limit per IP (file-based, no database needed)
$ip     = $_SERVER['REMOTE_ADDR'] ?? '0.0.0.0';
$rlFile = rtrim(sys_get_temp_dir(), '/\\') . '/nf_rl_' . sha1($ip . __DIR__) . '.json';
$now    = time();
$hits   = array_values(array_filter(
    json_decode((string) @file_get_contents($rlFile), true) ?: [],
    fn($t) => is_int($t) && $t > $now - (int) $cfg['rate_window']
));
if (count($hits) >= (int) $cfg['rate_limit']) respond(false, 429, ['error' => 'rate']);

// 4) Optional Cloudflare Turnstile
if (!empty($cfg['turnstile_secret'])) {
    $token = (string) ($_POST['cf-turnstile-response'] ?? '');
    $ctx   = stream_context_create(['http' => [
        'method'  => 'POST',
        'header'  => 'Content-Type: application/x-www-form-urlencoded',
        'content' => http_build_query(['secret' => $cfg['turnstile_secret'], 'response' => $token, 'remoteip' => $ip]),
        'timeout' => 8,
    ]]);
    $res = json_decode((string) @file_get_contents('https://challenges.cloudflare.com/turnstile/v0/siteverify', false, $ctx), true);
    if (empty($res['success'])) respond(false, 400, ['error' => 'captcha']);
}

// 5) Validate fields
$name    = clean('name', 100);
$company = clean('company', 120);
$email   = clean('email', 120);
$phone   = clean('phone', 40);
$country = strtoupper(clean('country', 2));
$type    = clean('type', 20);
$request = clean('request', 20);
$volume  = clean('volume', 10);
$message = clean('message', 3000);
$consent = ($_POST['consent'] ?? '') === '1';
$prodIn  = is_array($_POST['products'] ?? null) ? array_slice($_POST['products'], 0, 20) : [];

foreach ([$name, $company, $email, $phone] as $v) {
    if (preg_match('/[\r\n]|%0a|%0d|content-type:|bcc:/i', $v)) respond(true); // header injection attempt
}
if (mb_strlen($name) < 2)      respond(false, 422, ['field' => 'name']);
if ($company === '')           respond(false, 422, ['field' => 'company']);
if (!filter_var($email, FILTER_VALIDATE_EMAIL)) respond(false, 422, ['field' => 'email']);
if (mb_strlen($message) < 5)   respond(false, 422, ['field' => 'message']);
if (!$consent)                 respond(false, 422, ['field' => 'consent']);
if ($phone !== '' && !preg_match('/^[0-9+()\-.\/\s]{6,40}$/', $phone)) $phone = '';
if (preg_match_all('~(https?://|www\.)~i', $message) > (int) $cfg['max_links']) respond(false, 422, ['field' => 'message']);

$L = fn(string $group, string $key) => $labels[$group][$key] ?? '';
$products = [];
foreach ($prodIn as $p) {
    $p = (string) $p;
    if (isset($labels['products'][$p])) $products[] = $labels['products'][$p];
}
$country = isset($labels['countries'][$country]) ? $country : '';

// 6) Compose
$reqLabel = $L('requests', $request) ?: $L('requests', 'other');
$subject  = sprintf('%s %s – %s%s', $cfg['subject_prefix'], $reqLabel, $company, $country ? " ({$country})" : '');
$lines = [
    'Cerere nouă de pe site / New website inquiry',
    str_repeat('—', 44),
    'Solicitare:      ' . $reqLabel,
    'Nume:            ' . $name,
    'Companie:        ' . $company,
    'E-mail:          ' . $email,
    'Telefon:         ' . ($phone ?: '—'),
    'Țara:            ' . ($country ? $L('countries', $country) . " ({$country})" : '—'),
    'Tip companie:    ' . ($L('types', $type) ?: '—'),
    'Cantitate:       ' . ($L('volumes', $volume) ?: '—'),
    'Produse:         ' . ($products ? implode(', ', $products) : '—'),
    'Limba paginii:   ' . strtoupper($lang),
    str_repeat('—', 44),
    'Mesaj:',
    $message,
    str_repeat('—', 44),
    'Consimțământ GDPR: da · ' . date('Y-m-d H:i:s') . ' · IP ' . $ip,
];
$body = implode("\r\n", $lines);

// 7) Send
$from     = $cfg['from'];
$fromName = $cfg['from_name'];
$to       = array_values(array_filter(array_merge($cfg['to'], $cfg['cc'] ?? [])));
$encSubj  = '=?UTF-8?B?' . base64_encode($subject) . '?=';
$encName  = '=?UTF-8?B?' . base64_encode($fromName) . '?=';
$host     = preg_replace('/[^a-z0-9.\-]/i', '', $_SERVER['SERVER_NAME'] ?? 'localhost');
$headers  = [
    'Date: ' . date('r'),
    'From: ' . $encName . ' <' . $from . '>',
    'Reply-To: ' . $email,
    'Message-ID: <' . bin2hex(random_bytes(12)) . '@' . $host . '>',
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8',
    'Content-Transfer-Encoding: base64',
    'X-Mailer: NaturaFruct-site',
];
$encodedBody = chunk_split(base64_encode($body));

function smtp_send(array $s, string $from, array $to, string $headerBlock, string $body): bool
{
    $secure = $s['secure'] ?? 'tls';
    $remote = ($secure === 'ssl' ? 'ssl://' : 'tcp://') . $s['host'] . ':' . (int) ($s['port'] ?? 587);
    $fp = @stream_socket_client($remote, $errno, $errstr, 15);
    if (!$fp) return false;
    stream_set_timeout($fp, 15);
    $read = function () use ($fp): string {
        $data = '';
        while (($line = fgets($fp, 515)) !== false) {
            $data .= $line;
            if (isset($line[3]) && $line[3] === ' ') break;
        }
        return $data;
    };
    $cmd = function (string $c, array $ok) use ($fp, $read): bool {
        fwrite($fp, $c . "\r\n");
        return in_array((int) substr($read(), 0, 3), $ok, true);
    };
    $ehlo = 'EHLO ' . (preg_replace('/[^a-z0-9.\-]/i', '', $_SERVER['SERVER_NAME'] ?? '') ?: 'localhost');
    $ok = (int) substr($read(), 0, 3) === 220 && $cmd($ehlo, [250]);
    if ($ok && $secure === 'tls') {
        $ok = $cmd('STARTTLS', [220]) && stream_socket_enable_crypto($fp, true, STREAM_CRYPTO_METHOD_TLS_CLIENT) && $cmd($ehlo, [250]);
    }
    if ($ok && !empty($s['user'])) {
        $ok = $cmd('AUTH LOGIN', [334]) && $cmd(base64_encode($s['user']), [334]) && $cmd(base64_encode((string) $s['pass']), [235]);
    }
    $ok = $ok && $cmd('MAIL FROM:<' . $from . '>', [250]);
    foreach ($to as $rcpt) $ok = $ok && $cmd('RCPT TO:<' . $rcpt . '>', [250, 251]);
    $ok = $ok && $cmd('DATA', [354]);
    if ($ok) {
        $data = preg_replace('/^\./m', '..', $headerBlock . "\r\n\r\n" . $body);
        fwrite($fp, $data . "\r\n.\r\n");
        $ok = (int) substr($read(), 0, 3) === 250;
    }
    @fwrite($fp, "QUIT\r\n");
    fclose($fp);
    return $ok;
}

$sent = false;
if (!empty($cfg['smtp']['host'])) {
    $hdr  = array_merge($headers, ['To: ' . implode(', ', $cfg['to']), 'Subject: ' . $encSubj]);
    if (!empty($cfg['cc'])) $hdr[] = 'Cc: ' . implode(', ', $cfg['cc']);
    $sent = smtp_send($cfg['smtp'], $from, $to, implode("\r\n", $hdr), $encodedBody);
} else {
    $hdr = $headers;
    if (!empty($cfg['cc'])) $hdr[] = 'Cc: ' . implode(', ', $cfg['cc']);
    $sent = @mail(implode(', ', $cfg['to']), $encSubj, $encodedBody, implode("\r\n", $hdr), '-f' . $from);
}

if (!$sent) respond(false, 500, ['error' => 'send']);

$hits[] = $now;
@file_put_contents($rlFile, json_encode($hits), LOCK_EX);
respond(true);
